package dashboard.enterprise.agent.connector.provider.azure;
import com.fasterxml.jackson.databind.JsonNode; import dashboard.enterprise.agent.connector.credential.CredentialResolver; import dashboard.enterprise.agent.connector.model.*; import dashboard.enterprise.agent.connector.provider.AbstractLiveRestConnectorProvider; import dashboard.enterprise.agent.integration.work.model.WorkItem;
import java.net.http.HttpRequest; import java.nio.charset.StandardCharsets; import java.util.*;
public final class AzureDevOpsLiveConnectorProvider extends AbstractLiveRestConnectorProvider {
 public AzureDevOpsLiveConnectorProvider(String endpoint,CredentialResolver resolver){super(new ConnectorDefinition("mapaf.connector.definition/v1","azure-devops-live","Azure DevOps Live","AZURE_DEVOPS",ConnectorMode.LIVE,List.of("work-item.read","pull-request.read","pipeline.status.read","pipeline.trigger"),List.of(new SecretReference("mapaf.connector.secret/v1","pat","AZURE_DEVOPS_PAT"))),new ConnectorConnection("mapaf.connector.connection/v1","azure-devops-live-connection",endpoint,ConnectorMode.LIVE,Map.of()),90,resolver);}
 protected HttpRequest buildRequest(ConnectorRequest r){String id=String.valueOf(r.parameters().getOrDefault("id","1"));String path=switch(r.capabilityId()){case "work-item.read"->"/_apis/wit/workitems/"+id+"?api-version=7.1";case "pull-request.read"->"/_apis/git/pullrequests/"+id+"?api-version=7.1";case "pipeline.status.read"->"/_apis/build/builds/"+id+"?api-version=7.1";case "pipeline.trigger"->"/_apis/pipelines/"+id+"/runs?api-version=7.1";default->throw new IllegalArgumentException("Unsupported capability: "+r.capabilityId());};String auth=Base64.getEncoder().encodeToString((":"+secret("pat")).getBytes(StandardCharsets.UTF_8));HttpRequest.Builder b=HttpRequest.newBuilder(uri(path)).header("Authorization","Basic "+auth).header("Accept","application/json");return "pipeline.trigger".equals(r.capabilityId())?b.POST(HttpRequest.BodyPublishers.ofString("{}" )).build():b.GET().build();}
 protected Map<String,Object> normalize(String capability,JsonNode n){if("work-item.read".equals(capability)){JsonNode f=n.path("fields");WorkItem item=new WorkItem("mapaf.work-item/v1","azure",n.path("id").asText(),n.path("id").asText(),f.path("System.Title").asText(),f.path("System.Description").asText(),List.of(),f.path("System.WorkItemType").asText(),f.path("System.State").asText(),f.path("Microsoft.VSTS.Common.Priority").asText(),List.of(),f.path("System.AssignedTo").path("displayName").asText(),"",n.path("url").asText());return Map.of("workItem",item);}return Map.of("payload",MAPPER.convertValue(n,Map.class));}}
